                    const e1: u32 = k.a[0] +% @as(u32, 17);
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $04598  movea.l $16(a0), a1
                {
                    k.cy +%= 16;
                    const e0: u32 = k.a[0] +% @as(u32, 22);
                    k.a[1] = k.rl(e0);
                }
                // $0459c  move.b #$0, $33(a1)
                {
                    k.cy +%= 16;
                    const v = @as(u8, 0x0);
                    const e1: u32 = k.a[1] +% @as(u32, 51);
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $045a2  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

